If I have multiple user modes [modeA, modeB], and some args [SubclassA], I would expect to dispatch into mode A, mode B, then subclassA, but it is actually possible to make it so that we call into SubclassA's torch dispatch before that of mode B if we make mode A return NotImplemented.
import torch
from torch.utils._python_dispatch import TorchDispatchMode

class NotImplementedMode(TorchDispatchMode):
    def __torch_dispatch__(self, func, types, args=(), kwargs=None):
        print("NotImplementedMode", func)
        return NotImplemented

class TestMode(TorchDispatchMode):
    def __torch_dispatch__(self, func, types, args=(), kwargs=None):
        print("TestMode", func)
        kwargs = {} if kwargs is None else kwargs
        return func(*args, **kwargs)

class TestTensor(torch.Tensor):
    @staticmethod
    def __new__(cls, elem):
        r = torch.Tensor._make_subclass(cls, elem, elem.requires_grad)
        r.elem = elem
        return r

    @classmethod
    def __torch_dispatch__(self, func, types, args=(), kwargs=None):
        print("TestTensor", func)
        def unwrap(e):
            if isinstance(e, TestTensor):
                return e.elem
            else:
                return e

        def wrap(t):
            if isinstance(t, torch.Tensor):
                return TestTensor(t, self)
            else:
                return t

        return wrap(func(*tuple(unwrap(a) for a in args), **kwargs))

a = TestTensor(torch.tensor(1.))
with TestMode():
    with NotImplementedMode():
        a.clone()
