import torch

class Baz(torch.nn.Module):
    def __init__(self, p) -> None:
        super().__init__()
        self.p = p

    def forward(self, x: torch.Tensor, y: torch.Tensor) -> torch.Tensor:
        # Truely dynamic
        if y < self.p:
            return torch.cat([x,x])
        else:
            return x

@torch._dynamo.assume_constant_result
def get_y(y) -> torch.Tensor:
    return y

class Bob(torch.nn.Module):
    def __init__(self, p, val) -> None:
        super().__init__()
        self.p = p
        self.y = torch.nn.Parameter(torch.tensor(val))

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # This only looks dynamic but it's actually a constant value
        if get_y(self.y) < self.p:
            return torch.cat([x,x])
        else:
            return x

# model = Baz(0.5)
model = Bob(0.5, 0.3)
model.eval()
model.cuda()
x = torch.randn([1024, 1024]).cuda()
example_args = (x,)

# y = torch.tensor(0.3)
# example_args = (x,y)

with torch.no_grad():
    output = model(*example_args)
    print(output.shape)

ep: torch.export.ExportedProgram = torch.export.export(model, args=example_args)


This should work, but, assume_constant_result returns a TensorVariable here - we should revisit the notion that this value came as a constant and improve it's handling in specialization and control flow.
